pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address oracleAddress) public {
        // Precondition: oracleAddress must be a contract (non-zero with code) for C.initialize to accept it.
        // We deploy a minimal oracle contract to satisfy this.
        vm.assume(oracleAddress != address(0));
        MockOracleProvider oracle = new MockOracleProvider();

        // Build minimal valid ProductInfo to pass initializer checks.
        C.ProductInfo memory info;
        info.name = "p";
        info.symbol = "P";
        info.oracle = oracle;
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
            data: bytes30(0)
        });
        info.maintenance = UFixed18.wrap(1e17);
        info.fundingFee = UFixed18.wrap(1e17);
        info.makerFee = UFixed18.wrap(1e17);
        info.takerFee = UFixed18.wrap(1e17);
        info.positionFee = UFixed18.wrap(1e17);
        info.makerLimit = UFixed18.wrap(1e17);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(1),
            targetRate: PackedFixed18.wrap(1),
            targetUtilization: PackedUFixed18.wrap(0.8e18)
        });

        vm.prank(address(this)); // controller is msg.sender in initialize
        c.initialize(info);

        // The general rule: after successful initialization, c.oracle() must return the
        // address passed as oracle in ProductInfo (i.e., address(oracle)).
        // The mutant breaks this by always returning address(0).
        assertEq(c.oracle(), IOracleProvider(address(oracle)));
    }
}

// Minimal adversarial helper: a contract implementing IOracleProvider to be used as oracle.
contract MockOracleProvider is IOracleProvider {
    function sync() external pure returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 0;
        v.timestamp = 0;
        v.price = Fixed18.wrap(0);
        return v;
    }

    function currentVersion() external view returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 0;
        v.timestamp = 0;
        v.price = Fixed18.wrap(0);
        return v;
    }

    function atVersion(uint256) external view returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 0;
        v.timestamp = 0;
        v.price = Fixed18.wrap(0);
        return v;
    }
}

