pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address oracleAddr) public {
        // Exclude the zero address because the reference constructor also requires a non-zero oracle
        vm.assume(oracleAddr != address(0));

        // The reference implementation of oracle() must return the stored oracle address.
        // The mutant always returns address(0).
        // Assert that both return the same address. The fuzzer will find an address
        // where the reference returns a non-zero value and the mutant returns zero, making this fail.
        assertEq(c.oracle(), oracleAddr);
    }
}

