pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address oracleAddr) public {
        // oracleAddr must be a contract: code size > 0
        vm.assume(oracleAddr.code.length > 0);
        // It must be a valid OracleProvider, but we only need it to be a contract for address detection.
        // So we deploy a minimal contract that returns some price when called.
        // Initialize c with this oracle, all other params are zero/default.
        // The reference oracle() returns the given address, the mutant returns address(0).
        // The invariant: oracle() must return an address of a contract.

