        info.oracle = IOracleProvider(oracleAddr);
        // other fields can be zero/empty; they are not relevant
        vm.prank(address(this));
        c.initialize(info);

        address returnedOracle = address(c.oracle());
        assertTrue(returnedOracle.code.length > 0);
    }
}

