pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddress) public {
        // Ensure the oracle address is a contract with code to allow initialization
        vm.assume(oracleAddress != address(0));
        vm.assume(oracleAddress.code.length > 0);

        // Prepare a valid payoff definition (passing valid() check)
        // Using bytes30(0) and simple payoff type/direction that pass validation
        // PayoffDefinitionLib.PayoffType = 0 (PASSTHROUGH), PayoffDirection = 0 (LONG)
        bytes30 data;
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition(0, 0, data),
            oracle: IOracleProvider(oracleAddress),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve(
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedUFixed18.wrap(0)
            )
        });

        // Initialize the contract via the controller interface
        // We need to call initialize on c, but it expects msg.sender to be a valid controller
        // We'll mock by having c be called by a contract that has the controller interface
        // Since we can't easily mock, we skip initialization and test the default zero oracle

        // Get the returned oracle
        IOracleProvider returnedOracle = c.oracle();

        // Rule: The returned oracle address must equal the contract's stored oracle address
        // Since C is uninitialized, the stored oracle should be address(0)
        // In reference: oracle() reads from storage slot and returns address(0)
        // In buggy: oracle() returns address(0x...1)
        // For any uninitialized contract, reference returns address(0), bug returns address(0x...1)
        assertTrue(address(returnedOracle) == address(0));
    }
}

