    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddr, address payoffProvider, int8 payoffType, int8 payoffDir) public {
        vm.assume(oracleAddr != address(0) && oracleAddr != address(1));
        vm.assume(payoffType == 0 || payoffType == 1);
