pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(int256 oraclePrice, int256 transformScale) public {
        vm.assume(transformScale != 0);
        vm.assume(transformScale <= int256(type(int128).max) && transformScale >= int256(type(int128).min));
        vm.assume(oraclePrice >= int256(type(int128).min) && oraclePrice <= int256(type(int128).max));
        FixedPriceOracle oracle = new FixedPriceOracle(oraclePrice);
        ScaledPayoff payoff = new ScaledPayoff(transformScale);
        C.ProductInfo memory info;
        info.oracle = IOracleProvider(address(oracle));
        info.payoffDefinition = PayoffDefinitionLib.PayoffDefinition(PayoffDefinitionLib.PayoffType.PASSTHROUGH, PayoffDefinitionLib.PayoffDirection.LONG, bytes30(abi.encodePacked(address(payoff))));
        info.name = "test";
        info.symbol = "T";
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedUFixed18.wrap(0));
        c.initialize(info);
        IOracleProvider.OracleVersion memory cv = c.currentVersion();
        Fixed18 expectedPrice = Fixed18.wrap(oraclePrice * transformScale);
        assertTrue(Fixed18.unwrap(cv.price) == Fixed18.unwrap(expectedPrice));
    }
}

contract FixedPriceOracle {
    int256 price;
    constructor(int256 _price) { price = _price; }
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(block.timestamp, block.timestamp, Fixed18.wrap(price));
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(block.timestamp, block.timestamp, Fixed18.wrap(price));
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(block.timestamp, block.timestamp, Fixed18.wrap(price));
    }
}

contract ScaledPayoff {
    int256 scale;
    constructor(int256 _scale) { scale = _scale; }
    function transform(Fixed18 price) external view returns (Fixed18) {
        return Fixed18.wrap(Fixed18.unwrap(price) * scale / 1e18);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracle, uint256 price) public {
        vm.assume(price > 0 && price < type(int256).max / 1e18);
        // Deploy a mock oracle that returns the fuzzed price
        MockOracle mock = new MockOracle(price);
        vm.assume(oracle != address(mock));
        // Build product info with a PASSTHROUGH LONG payoff (no transformation)
        // In this case, the transformed price must equal the raw price from the oracle.
        PayoffDefinitionLib.PayoffDefinition memory payoffDef = PayoffDefinitionLib.PayoffDefinition(
            PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            PayoffDefinitionLib.PayoffDirection.LONG,
            bytes30(0)
        );
        IProduct.ProductInfo memory info = IProduct.ProductInfo(
            "",
            "",
            payoffDef,
            IOracleProvider(address(mock)),
            UFixed18.wrap(1e18),
            UFixed18.wrap(0),
            UFixed18.wrap(0),
            UFixed18.wrap(0),
            UFixed18.wrap(0),
            UFixed18.wrap(1e18),
            JumpRateUtilizationCurve(
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedUFixed18.wrap(1e18)
            )
        );
        vm.prank(address(this));
        c.initialize(info);
        // Trigger oracle sync so that currentVersion is callable
        mock.setVersion(1, uint256(price));
        IOracleProvider.OracleVersion memory v = c.currentVersion();
        // For PASSTHROUGH LONG, the transformed price must equal the raw oracle price.
        assertEq(Fixed18.unwrap(v.price), int256(price));
    }
}

contract MockOracle is IOracleProvider {
    int256 public price;
    uint256 public version;
    constructor(uint256 _price) { price = int256(_price); version = 1; }
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(version, block.timestamp, Fixed18.wrap(price));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(version, block.timestamp, Fixed18.wrap(price));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(version, block.timestamp, Fixed18.wrap(price));
    }
    function setVersion(uint256 v, uint256 p) external { version = v; price = int256(p); }
}

library PayoffDefinitionLib {
    enum PayoffType { PASSTHROUGH, TRANSFORM }
    enum PayoffDirection { LONG, SHORT }
    struct PayoffDefinition {
        PayoffType payoffType;
        PayoffDirection payoffDirection;
        bytes30 data;
    }
}

library Fixed18Lib {
    int256 private constant BASE = 1e18;
    function wrap(int256 a) internal pure returns (Fixed18) { return Fixed18.wrap(a); }
}

library UFixed18Lib {
    function wrap(uint256 a) internal pure returns (UFixed18) { return UFixed18.wrap(a); }
    function ZERO() internal pure returns (UFixed18) { return UFixed18.wrap(0); }
    function ONE() internal pure returns (UFixed18) { return UFixed18.wrap(1e18); }
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

struct PayoffDefinition {
    PayoffDefinitionLib.PayoffType payoffType;
    PayoffDefinitionLib.PayoffDirection payoffDirection;
    bytes30 data;
}

using PayoffDefinitionLib for PayoffDefinition global;

type Fixed18 is int256;

type UFixed18 is uint256;

type PackedFixed18 is int128;

type PackedUFixed18 is uint128;

interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256) external view returns (OracleVersion memory);
}

interface IProduct {
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
