// Minimal oracle that returns a configurable version and price.
contract IOracleProviderHarness is IOracleProvider {
    uint256 private _version;
    Fixed18 private _price;

    constructor(uint256 version_, int256 price_) {
        _version = version_;
        _price = Fixed18.wrap(price_);
    }

    function sync() external returns (OracleVersion memory) {
        return OracleVersion(_version, block.timestamp, _price);
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(_version, block.timestamp, _price);
    }

    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory) {
        // Return the stored version and price regardless of the requested version,
        // so we can observe the mutant calling atVersion(1) and getting version 1.
        // The reference never calls atVersion(1) via currentVersion(), so it is unaffected.
        return OracleVersion(oracleVersion, block.timestamp, _price);
    }
}

