pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal helper: a valid IController contract to initialize C with.
contract MockController {
    function isProduct(address) external pure returns (bool) { return false; }
    function paused() external pure returns (bool) { return false; }
    function owner(uint256) external view returns (address) { return address(this); }
    function coordinatorFor(address) external pure returns (uint256) { return 0; }
    function collateral() external view returns (address) { return address(0); }
    function incentivizer() external view returns (address) { return address(0); }
    function minFundingFee() external pure returns (uint256) { return 0; }
    function multiInvoker() external view returns (address) { return address(0); }
}

contract InvMutTest is Test {
    C c;
    MockController controller;

    function setUp() public {
        controller = new MockController();
        c = new C();
    }

    function testFuzz_property(address productBeaconAddr) public {
        // productBeaconAddr must be a contract for initialization to succeed.
        // The fuzzer will supply an address; we deploy a minimal valid beacon so
        // initialization does not fail due to non-contract address.
        vm.assume(productBeaconAddr != address(0));
        vm.assume(productBeaconAddr != address(this));
        vm.assume(productBeaconAddr != address(c));
        vm.assume(productBeaconAddr != address(controller));

        // Deploy a minimal beacon that implements IBeacon
        MockBeacon beacon = new MockBeacon();

        // Ensure the fuzzed address is this contract for the call to succeed.
        // The bug is about controller() returning wrong value, not about
        // initialization failure. We always initialize with the same correct
        // controller and beacon.
        C.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(address(0)); // Not used in this test
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(0)
        );
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            PayoffDefinitionLib.PayoffDirection.LONG,
            bytes30(0)
        );

        // We need to initialize C. The initialize function is called by the
        // controller (msg.sender) and expects msg.sender to be an IController
        // that has isProduct returning false for the new contract.
        // We prank as the MockController to simulate proper initialization.
        vm.prank(address(controller));
        c.initialize(info);

        // After initialization, controller() must return the address we initialized with.
        // The buggy version returns address(0) always, violating this rule.
        assertEq(address(c.controller()), address(controller));
    }
}

// Minimal IBeacon implementation
contract MockBeacon {
    function implementation() external pure returns (address) {
        return address(0);
    }
}
